"""Build a code-driven review page from real rules and unchanged A3 geometry (not a game capture)."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'artifacts/abyss-feel-preview.json').read_text())
template=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>阿比斯 0.54 · 操作与挥镰预览</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#100d18;color:#e9e0f4;font:15px/1.5 'Microsoft YaHei',sans-serif}main{max-width:1280px;margin:28px auto;padding:0 24px}h1{font-size:28px;margin:0}p{color:#b6a6c7;margin:8px 0 20px}button,select{color:#f0e3ff;background:#32233f;border:1px solid #624480;padding:8px 14px;border-radius:8px;cursor:pointer}button.active{background:#78519e}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.screen{position:relative;aspect-ratio:16/9;overflow:hidden;border:1px solid #534164;border-radius:16px;background:linear-gradient(#334554 0%,#5c4e61 47%,#293e37 48%,#15261e 100%)}.tag{position:absolute;left:2%;top:3%;font-size:12px;color:#d6cfdf}.native{position:absolute;border:1px dashed #b4c8cc80;border-radius:12px;display:grid;place-items:center;color:#d3e2db;font-size:13px;background:#25393466}.hotbar{left:32.8%;top:91.1%;width:34.4%;height:7.8%;border-radius:4px}.cross{position:absolute;left:50%;top:50%;font-size:22px;color:#c8d9d6}.skill{position:absolute;aspect-ratio:1;background-image:url('../../../src/SCIEPort/Assets/Textures/AbyssSkillsV1.png');background-size:200% 200%;border:0;padding:0;border-radius:50%;filter:drop-shadow(0 2px 3px #000a)}.caption{position:absolute;left:0;bottom:16%;width:100%;text-align:center;color:#efddff;font-size:clamp(7px,1.1vw,12px);text-shadow:0 1px 3px black}.count{position:absolute;left:0;top:30%;width:100%;text-align:center;font-size:24px;color:white;text-shadow:0 1px 3px black}.nameplate{position:absolute;color:#dec5f0;font-size:12px}.motion{margin-top:24px;padding:20px;background:#1d1727;border-radius:16px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}canvas{width:100%;background:#253b43;border:1px solid #51435f;border-radius:8px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.controls input{flex:1;min-width:160px;accent-color:#bd8eff}.note{font-size:12px;color:#aa98bb}h3{font-size:14px;margin:0 0 6px}
</style><main><div class="top"><div><h1>阿比斯 · 挥镰与圆形技能</h1><p>0.54.0 / 实际规则导出的布局 + A3 几何的软件投影，非游戏截图</p></div><button id="mirror">切换左手布局</button></div><div class="screen" id="screen"><span class="tag">1280 × 720 逻辑视口 · 原生控件仅作位置示意</span><div class="cross">+</div><div id="look" class="native">查看</div><div id="move" class="native">移动</div><div class="native hotbar">快捷栏 / 不覆盖</div></div><section class="motion"><div class="controls"><select id="stage"><option value="0">第一斩 · 横扫</option><option value="1">第二斩 · 回斩</option><option value="2">第三斩 · 挑斩</option><option value="3">蓄力重斩</option></select><button id="play">播放动作</button><input id="phase" type="range" min="0" max="100" value="72"><span id="phaseText">72%</span></div><div class="pair"><div><h3>调整前 / 只有小幅旋转</h3><canvas id="old" width="600" height="320"></canvas></div><div><h3>0.54 / 移握 + 横扫 + 回收</h3><canvas id="new" width="600" height="320"></canvas></div></div><p class="note">使用未修改的 DAE 对应几何、CSV 持握参数与目标原生 10 × dt 插值；忽略视角晃动和人体骨骼。普攻范围 3 → 4.5 格，蓄力 3.5 → 5.5 格。真实裁切、遮挡、手感及 Android 表现仍需实测。</p></section></main>
<script>const fixture=__FIXTURE__;let mirrored=false;const names=['星门','断界斩','瞬狩','终焉坍缩'];let triangles,palette,playing=false;function layout(){const f=fixture.layouts[mirrored?1:0];for(const id of ['look','move']){const r=f[id],e=document.getElementById(id);Object.assign(e.style,{left:r[0]/12.8+'%',top:r[1]/7.2+'%',width:r[2]/12.8+'%',height:r[3]/7.2+'%'});}document.querySelectorAll('.skill').forEach(e=>e.remove());for(const r of f.icons){let e=document.createElement('button');e.className='skill';e.title=names[r.slot];Object.assign(e.style,{left:r.x/12.8+'%',top:r.y/7.2+'%',width:r.size/12.8+'%',backgroundPosition:(r.slot%2?'100%':'0%')+' '+(r.slot>1?'100%':'0%')});e.innerHTML='<span class="caption">'+names[r.slot]+'</span>';e.onclick=()=>{e.innerHTML='<span class="count">'+[0,10,15,180][r.slot]+'</span><span class="caption">'+names[r.slot]+'</span>';};document.getElementById('screen').append(e);}}document.getElementById('mirror').onclick=()=>{mirrored=!mirrored;layout();};layout();
function quaternion(p){let [pitch,yaw,roll]=p.map(x=>x/2),sy=Math.sin(yaw),cy=Math.cos(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch),sr=Math.sin(roll),cr=Math.cos(roll);return [cy*sp*cr+sy*cp*sr,sy*cp*cr-cy*sp*sr,cy*cp*sr-sy*sp*cr,cy*cp*cr+sy*sp*sr];}
function rotate(v,q){let [x,y,z,w]=q,[a,b,c]=v;let tx=2*(y*c-z*b),ty=2*(z*a-x*c),tz=2*(x*b-y*a);return [a+w*tx+y*tz-z*ty,b+w*ty+z*tx-x*tz,c+w*tz+x*ty-y*tx];}
function sampled(stage,phase,old){if(phase>=1)return {rotation:[0,0,0],offset:[0,0,0]};if(old){let arc=Math.sin(phase*Math.PI),r=stage===0?[0,(phase*2-1)*1.15,-arc*.3]:stage===1?[0,(1-phase*2)*1.3,arc*.35]:[(phase*2-1)*1.2,0,arc*.25];return {rotation:r,offset:[0,0,0]};}return fixture.poses[stage*101+Math.round(phase*100)];}
function smoothed(stage,phase,old){let r=[0,0,0],o=[0,0,0],duration=[.35,.42,.58,.85][stage],k=Math.min(1,duration/100*10);for(let frame=0;frame<=Math.round(phase*100);frame++){let p=sampled(stage,frame/100,old);for(let i=0;i<3;i++){r[i]+=(p.rotation[i]-r[i])*k;o[i]+=(p.offset[i]-o[i])*k;}}return {rotation:r,offset:o};}
function render(id,pose){const canvas=document.getElementById(id),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.fillStyle='#314753';c.fillRect(0,0,w,h);c.fillStyle='#203a32';c.fillRect(0,h*.53,w,h*.47);c.strokeStyle='#b0bdb9';c.beginPath();c.moveTo(w/2-7,h/2);c.lineTo(w/2+7,h/2);c.moveTo(w/2,h/2-7);c.lineTo(w/2,h/2+7);c.stroke();if(!triangles)return;let q=quaternion([pose.rotation[0],pose.rotation[1]-8*Math.PI/180,pose.rotation[2]-8*Math.PI/180]),off=[.50+pose.offset[0]*2,-.38+pose.offset[1]*2,-.95+pose.offset[2]*2],focal=h*.5/Math.tan(75*Math.PI/360),polys=[];for(const t of triangles){let vs=t.slice(0,3).map(v=>rotate(v.map(x=>x*.46),q).map((x,i)=>x+off[i]));if(vs.some(v=>v[2]>=-.03))continue;let points=vs.map(v=>[w/2+focal*v[0]/-v[2],h/2-focal*v[1]/-v[2]]);if(points.every(v=>v[0]<0)||points.every(v=>v[0]>w)||points.every(v=>v[1]<0)||points.every(v=>v[1]>h))continue;let n=rotate(t[3],q),shade=t[4]>=12?1:.44+.56*Math.max(0,n[0]*-.3+n[1]*.5-n[2]*.8),color=palette[t[4]].map(x=>Math.round(x*shade));polys.push([vs.reduce((s,v)=>s+v[2],0),points,'rgb('+color.join(',')+')']);}polys.sort((a,b)=>a[0]-b[0]);for(const [,points,color] of polys){c.fillStyle=color;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill();}}
function draw(){let phase=+document.getElementById('phase').value/100,stage=+document.getElementById('stage').value;document.getElementById('phaseText').textContent=Math.round(phase*100)+'%';render('old',smoothed(stage,phase,true));render('new',smoothed(stage,phase,false));}document.getElementById('phase').oninput=draw;document.getElementById('stage').onchange=draw;document.getElementById('play').onclick=()=>{if(playing)return;playing=true;let start=performance.now();function tick(){let progress=Math.min(100,(performance.now()-start)/14);document.getElementById('phase').value=progress;draw();if(progress<100)requestAnimationFrame(tick);else playing=false;}tick();};Promise.all([fetch('geometry.json').then(r=>r.json()),fetch('palette.json').then(r=>r.json())]).then(([g,p])=>{triangles=g.flatMap(m=>m[1]);palette=p;draw();});</script></html>'''
(root/'docs/assets/abyss-reaper/preview-controls.html').write_text(template.replace('__FIXTURE__',json.dumps(data,separators=(',',':'))),encoding='utf-8')
print('Wrote software preview; no game, weapon or generated image modified.')
